# Segmented diagnostics show which subsets are actually hitting instead of one aggregate shadow rate.
rep(lip,'import android.database.sqlite.SQLiteDatabase;\n','import android.database.sqlite.SQLiteDatabase;\n\nimport org.json.JSONObject;\n')
rep(lip,
'''    synchronized PipelineStats pipelineStats(){\n''',
'''    synchronized SegmentedStats segmentedStats(){\n        SegmentedStats s=new SegmentedStats();long[] b=todayBounds();\n        try(SQLiteDatabase db=open();Cursor c=db.rawQuery("SELECT status,features FROM shadow_samples WHERE resolved_ms>=? AND resolved_ms<? AND status IN ('SUCCESS','FAIL','TIMEOUT')",new String[]{String.valueOf(b[0]),String.valueOf(b[1])})){\n            while(c.moveToNext()){String status=c.getString(0),raw=c.getString(1);boolean hit="SUCCESS".equals(status);try{JSONObject f=new JSONObject(raw);double ep=f.optDouble("earlyPressure",0),breadth=f.optDouble("breadthPct",-1);String setup=f.optString("setupType","");boolean hod=f.optBoolean("bullishHodBreakout",false)||"BULLISH HOD BREAKOUT".equals(setup);if(ep>=90){s.early90N++;if(hit)s.early90Hits++;}if(breadth>=55){s.bullN++;if(hit)s.bullHits++;}if(hod){s.hodBreakN++;if(hit)s.hodBreakHits++;}if("MICRO BREAKOUT".equals(setup)||"BULLISH HOD BREAKOUT".equals(setup)){s.microN++;if(hit)s.microHits++;}}catch(Exception ignore){}}\n        }catch(Exception ignore){}\n        return s;\n    }\n\n    synchronized PipelineStats pipelineStats(){\n''')
rep(lip,
'''    static final class PipelineStats{int observed,shadowObserved,qualified,pending,hits,stops,timeouts;}\n''',
'''    static final class PipelineStats{int observed,shadowObserved,qualified,pending,hits,stops,timeouts;}\n    static final class SegmentedStats{int early90N,early90Hits,bullN,bullHits,hodBreakN,hodBreakHits,microN,microHits;}\n''')

