(TEST/'BullishHodBreakoutTest.java').write_text('''package com.suhas.nseunifiedscanner;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\npublic class BullishHodBreakoutTest {\n @Test public void strongBullishPressureCanCrossSmallHodGap(){assertTrue(TradeSetupLogic.bullishHodBreakoutSetup(68,92,1.8,57,true,true,0.08,0.61,0.12,120_000_000,-0.20,false,0.24,false));}\n @Test public void lowVolumeCannotOverrideHod(){assertFalse(TradeSetupLogic.bullishHodBreakoutSetup(70,94,0.7,56,true,true,0.05,0.62,0.10,150_000_000,-0.12,false,0.18,false));}\n @Test public void priorHodRejectionCannotUseOverride(){assertFalse(TradeSetupLogic.bullishHodBreakoutSetup(72,95,4.2,58,true,true,0.06,0.64,0.10,200_000_000,-0.18,true,0.20,false));}\n @Test public void lateSpikeCannotUseOverride(){assertFalse(TradeSetupLogic.bullishHodBreakoutSetup(72,96,4.0,58,true,true,0.08,0.65,0.10,220_000_000,-0.18,false,1.20,true));}\n @Test public void exceptionalVolumeAllowsSlightlyDeeperCross(){assertTrue(TradeSetupLogic.bullishHodBreakoutSetup(72,91,5.5,59,true,false,0.12,0.54,0.16,180_000_000,-0.36,false,0.15,false));}\n}\n''')

